@startuml

class Animal {
  + ID
  + name
  + breed
}

class Owner {
  + ID
  + name
  + address
  + phone
}

class Breed {
  + name
}

class Physician {
  + ID
  + name
  + address
  + phone
}

class Appointment {
  + start_date_time
}

class Condition {
  + common_name
  + scientific_name
}

Owner "0..1" -- "*" Animal : owns
Animal "*" -- "1" Breed : is of
Physician "1" -- "*" Appointment : is responsible for
Animal "1" -- "*" Appointment : is attended
Owner "1" -- "*" Appointment : is owner of
Breed "*" -- "*" Condition : has common conditions

@enduml

